import fs from "node:fs";
import path from "node:path";

const base = process.cwd();
const categoryCatalogPath = path.join(base, "src/learning/categoryCatalog.ts");
const activationPolicyPath = path.join(base, "public/content/activation/active-sessions.json");
const outputPath = path.join(base, "src/learning/attemptRegistry.generated.ts");
const categoryCatalog = fs.readFileSync(categoryCatalogPath, "utf8");
const activationPolicy = JSON.parse(fs.readFileSync(activationPolicyPath, "utf8"));
const categoryPattern = /(reading_units|vowels_sukun|shaddah|article_al|linking|fluent_reading):\s*\{[\s\S]*?manifestUrl:\s*"([^"]+)"[\s\S]*?blueprintUrl:\s*"([^"]+)"/g;
const arabicPattern = /[\u0600-\u06ff]/u;
const resources = [];
let match;
while ((match = categoryPattern.exec(categoryCatalog)) !== null) {
  resources.push({ category: match[1], manifestUrl: match[2], blueprintUrl: match[3] });
}

if (resources.length !== 6) {
  throw new Error(`Expected 6 active category resources, found ${resources.length}.`);
}

const registry = {};
const interactionPolicies = {};
const availableSessions = {};
for (const { category, manifestUrl, blueprintUrl } of resources) {
  const blueprintPath = blueprintUrl.replace(/^\//, "public/");
  const manifestPath = manifestUrl.replace(/^\//, "public/");
  const blueprint = JSON.parse(fs.readFileSync(path.join(base, blueprintPath), "utf8"));
  const manifest = JSON.parse(fs.readFileSync(path.join(base, manifestPath), "utf8"));
  if (blueprint.category !== category) {
    throw new Error(`Category mismatch for ${blueprintUrl}: expected ${category}, got ${blueprint.category}.`);
  }

  const policySessionIds = activationPolicy[category];
  if (!Array.isArray(policySessionIds)) {
    throw new Error(`Missing active-session policy for category ${category}.`);
  }
  if (new Set(policySessionIds).size !== policySessionIds.length) {
    throw new Error(`Duplicate active-session policy entry for category ${category}.`);
  }
  for (const sessionId of policySessionIds) {
    if (typeof sessionId !== "string" || sessionId.length === 0 || arabicPattern.test(sessionId)) {
      throw new Error(`Invalid active-session policy id for category ${category}.`);
    }
  }

  const manifestItems = new Map((manifest.items ?? []).map((item) => [item.id, item]));
  const sessions = {};
  const sessionPolicies = {};
  const activeSessionIds = [];
  const blueprintSessionIds = new Set();
  const policySet = new Set(policySessionIds);
  for (const session of blueprint.sessions ?? []) {
    if (typeof session.id !== "string" || session.id.length === 0 || arabicPattern.test(session.id)) {
      throw new Error(`Invalid session id in ${blueprintUrl}.`);
    }
    blueprintSessionIds.add(session.id);
    const itemIds = [];
    const perItemPolicies = {};
    let sessionAvailable = true;
    for (const interaction of session.interactions ?? []) {
      if (typeof interaction.itemId !== "string" || interaction.itemId.length === 0 || arabicPattern.test(interaction.itemId)) {
        throw new Error(`Invalid item id in ${blueprintUrl}/${session.id}.`);
      }
      if (interaction.timing !== "off" && interaction.timing !== "hidden") {
        throw new Error(`Invalid timing policy in ${blueprintUrl}/${session.id}/${interaction.itemId}.`);
      }
      if (interaction.voice !== "off" && interaction.voice !== "optional") {
        throw new Error(`Invalid voice policy in ${blueprintUrl}/${session.id}/${interaction.itemId}.`);
      }
      const observationPolicy = { timing: interaction.timing, voice: interaction.voice };
      const existingPolicy = perItemPolicies[interaction.itemId];
      if (existingPolicy && JSON.stringify(existingPolicy) !== JSON.stringify(observationPolicy)) {
        throw new Error(`Ambiguous observation policy for repeated item ${blueprintUrl}/${session.id}/${interaction.itemId}.`);
      }
      perItemPolicies[interaction.itemId] = observationPolicy;
      itemIds.push(interaction.itemId);
      const item = manifestItems.get(interaction.itemId);
      if (!item || item.active !== true || item.eligibleForActiveLesson !== true) {
        sessionAvailable = false;
      }
    }
    sessions[session.id] = itemIds;
    sessionPolicies[session.id] = perItemPolicies;
    if (policySet.has(session.id)) {
      if (!sessionAvailable || itemIds.length === 0) {
        throw new Error(`Active-session policy references unavailable session ${category}/${session.id}.`);
      }
      activeSessionIds.push(session.id);
    }
  }
  for (const sessionId of policySet) {
    if (!blueprintSessionIds.has(sessionId)) {
      throw new Error(`Active-session policy references unknown session ${category}/${sessionId}.`);
    }
  }
  registry[category] = sessions;
  interactionPolicies[category] = sessionPolicies;
  availableSessions[category] = activeSessionIds;
}

const source = `// Generated by scripts/generate-attempt-registry.mjs. Do not edit by hand.\nimport type { AttemptRecord, ExerciseCategory } from "./types";\n\ntype ObservationPolicy = { timing: "off" | "hidden"; voice: "off" | "optional" };\n\nconst AUTHORIZED_ATTEMPTS: Record<ExerciseCategory, Record<string, readonly string[]>> = ${JSON.stringify(registry, null, 2)};\n\nconst INTERACTION_POLICIES: Record<ExerciseCategory, Record<string, Record<string, ObservationPolicy>>> = ${JSON.stringify(interactionPolicies, null, 2)};\n\nconst AVAILABLE_SESSIONS: Record<ExerciseCategory, readonly string[]> = ${JSON.stringify(availableSessions, null, 2)};\n\nexport function isSessionKnownToControlledBlueprint(\n  category: ExerciseCategory,\n  sessionId: string,\n): boolean {\n  return Object.prototype.hasOwnProperty.call(AUTHORIZED_ATTEMPTS[category] ?? {}, sessionId);\n}\n\nexport function isAttemptAuthorizedByControlledBlueprint(\n  attempt: Pick<AttemptRecord, "category" | "sessionId" | "itemId">,\n): boolean {\n  if (!isSessionAvailableForActiveLesson(attempt.category, attempt.sessionId)) return false;\n  return AUTHORIZED_ATTEMPTS[attempt.category]?.[attempt.sessionId]?.includes(attempt.itemId) ?? false;\n}\n\nexport function controlledObservationPolicyForAttempt(\n  attempt: Pick<AttemptRecord, "category" | "sessionId" | "itemId">,\n): ObservationPolicy | undefined {\n  if (!isAttemptAuthorizedByControlledBlueprint(attempt)) return undefined;\n  return INTERACTION_POLICIES[attempt.category]?.[attempt.sessionId]?.[attempt.itemId];\n}\n\nexport function isSessionAvailableForActiveLesson(\n  category: ExerciseCategory,\n  sessionId: string,\n): boolean {\n  return AVAILABLE_SESSIONS[category]?.includes(sessionId) ?? false;\n}\n\nexport function hasSessionAvailableForActiveLesson(category: ExerciseCategory): boolean {\n  return (AVAILABLE_SESSIONS[category]?.length ?? 0) > 0;\n}\n\nexport function availableSessionIdsForActiveLesson(category: ExerciseCategory): readonly string[] {\n  return AVAILABLE_SESSIONS[category] ?? [];\n}\n\nfunction correctAttemptCounts(\n  attempts: AttemptRecord[],\n  category: ExerciseCategory,\n  sessionId: string,\n): Map<string, number> {\n  const counts = new Map<string, number>();\n  for (const attempt of attempts) {\n    if (attempt.category !== category || attempt.sessionId !== sessionId || attempt.outcome !== "correct") continue;\n    counts.set(attempt.itemId, (counts.get(attempt.itemId) ?? 0) + 1);\n  }\n  return counts;\n}\n\nfunction requiredItemCounts(requiredItemIds: readonly string[]): Map<string, number> {\n  const counts = new Map<string, number>();\n  for (const itemId of requiredItemIds) counts.set(itemId, (counts.get(itemId) ?? 0) + 1);\n  return counts;\n}\n\nexport function sessionCompletionCountFromAuthorizedAttempts(\n  category: ExerciseCategory,\n  sessionId: string,\n  attempts: AttemptRecord[],\n): number {\n  if (!isSessionAvailableForActiveLesson(category, sessionId)) return 0;\n  const requiredItemIds = AUTHORIZED_ATTEMPTS[category]?.[sessionId];\n  if (!requiredItemIds?.length) return 0;\n  const requiredCounts = requiredItemCounts(requiredItemIds);\n  const correctCounts = correctAttemptCounts(attempts, category, sessionId);\n  return Math.min(\n    ...Array.from(requiredCounts.entries()).map(([itemId, required]) =>\n      Math.floor((correctCounts.get(itemId) ?? 0) / required)\n    ),\n  );\n}\n\nexport function sessionResumeIndexFromAuthorizedAttempts(\n  category: ExerciseCategory,\n  sessionId: string,\n  attempts: AttemptRecord[],\n): number {\n  if (!isSessionAvailableForActiveLesson(category, sessionId)) return 0;\n  const requiredItemIds = AUTHORIZED_ATTEMPTS[category]?.[sessionId];\n  if (!requiredItemIds?.length) return 0;\n  const correctCounts = correctAttemptCounts(attempts, category, sessionId);\n  const requiredCounts = requiredItemCounts(requiredItemIds);\n  const completedCycles = sessionCompletionCountFromAuthorizedAttempts(category, sessionId, attempts);\n  const consumed = new Map<string, number>();\n  for (let index = 0; index < requiredItemIds.length; index += 1) {\n    const itemId = requiredItemIds[index];\n    const occurrenceInCycle = (consumed.get(itemId) ?? 0) + 1;\n    const requiredOccurrence = completedCycles * (requiredCounts.get(itemId) ?? 1) + occurrenceInCycle;\n    if ((correctCounts.get(itemId) ?? 0) < requiredOccurrence) return index;\n    consumed.set(itemId, occurrenceInCycle);\n  }\n  return 0;\n}\n\nexport function completedSessionIdsFromAuthorizedAttempts(attempts: AttemptRecord[]): string[] {\n  const completed: string[] = [];\n  for (const category of Object.keys(AUTHORIZED_ATTEMPTS) as ExerciseCategory[]) {\n    for (const sessionId of Object.keys(AUTHORIZED_ATTEMPTS[category])) {\n      if (!isSessionAvailableForActiveLesson(category, sessionId)) continue;\n      if (sessionCompletionCountFromAuthorizedAttempts(category, sessionId, attempts) > 0) completed.push(sessionId);\n    }\n  }\n  return completed;\n}\n`;

fs.writeFileSync(outputPath, source, "utf8");
console.log(`Generated controlled attempt registry for ${resources.length} categories.`);
